<?php
require_once __DIR__.'/../config/koneksi.php';require_once __DIR__.'/../config/tahap4.php';require_login('admin');$u=current_user();$err='';
// Hindari Fatal Error bila tabel transaksi belum dibuat oleh migrasi.
$requiredT4=['aturan_komisi','invoice','komisi_transaksi','pembayaran','audit_log'];
$missingT4=[];
$checkT4=$pdo->prepare('SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name=?');
foreach($requiredT4 as $tableT4){$checkT4->execute([$tableT4]);if(!(int)$checkT4->fetchColumn())$missingT4[]=$tableT4;}
if($missingT4){http_response_code(503);$pageTitle='Admin transaksi';require __DIR__.'/../includes/header.php';echo '<main class="dashboard-main"><section class="dashboard-panel"><h1 class="dashboard-title">Modul transaksi belum siap</h1><p>Database Tahap 4 belum lengkap. Tabel berikut belum ditemukan: <b>'.htmlspecialchars(implode(', ',$missingT4),ENT_QUOTES,'UTF-8').'</b>.</p><p>Backup database, jalankan <code>database/migrations/004_tahap4_perbaikan.sql</code>, kemudian <code>database/migrasi_lamaran_pekerjaan.sql</code>, lalu muat ulang halaman ini.</p></section></main>';require __DIR__.'/../includes/footer.php';exit;}

if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$act=$_POST['action']??'';if($act==='commission'){$name=trim($_POST['nama']??'Komisi NusaKarya');$rate=10.0;if($name==='')throw new RuntimeException('Nama aturan komisi wajib diisi.');$pdo->beginTransaction();$pdo->exec('UPDATE aturan_komisi SET is_aktif=0 WHERE is_aktif=1');$q=$pdo->prepare('INSERT INTO aturan_komisi (nama,persentase,berlaku_mulai,is_aktif,dibuat_oleh) VALUES (?,?,NOW(),1,?)');$q->execute([$name,$rate,$u['id']]);t4_audit($pdo,(int)$u['id'],'commission.activated','aturan_komisi',(int)$pdo->lastInsertId(),['rate'=>$rate]);$pdo->commit();}elseif($act==='verify'){$pid=(int)$_POST['payment_id'];$decision=$_POST['decision']??'';$note=trim($_POST['note']??'');$pdo->beginTransaction();$q=$pdo->prepare('SELECT p.*,i.pesanan_id,i.id invoice_id,i.status invoice_status FROM pembayaran p JOIN invoice i ON i.id=p.invoice_id WHERE p.id=? FOR UPDATE');$q->execute([$pid]);$p=$q->fetch();if(!$p||$p['status']!=='Menunggu Verifikasi')throw new RuntimeException('Pembayaran tidak menunggu verifikasi.');if($decision==='approve'){if($p['invoice_status']==='Lunas')throw new RuntimeException('Invoice sudah lunas melalui pembayaran lain. Periksa kemungkinan pembayaran ganda.');$pdo->prepare("UPDATE pembayaran SET status='Berhasil',diverifikasi_at=NOW(),diverifikasi_oleh=?,catatan_verifikasi=? WHERE id=?")->execute([$u['id'],$note?:null,$pid]);$pdo->prepare("UPDATE invoice SET status='Lunas',lunas_at=NOW() WHERE id=?")->execute([$p['invoice_id']]);$pdo->prepare("UPDATE pesanan SET status=CASE WHEN lamaran_id IS NOT NULL AND jenis_pelaksanaan='online' THEN 'Selesai' ELSE status END,status_pembayaran='Berhasil',status_pekerjaan=CASE WHEN lamaran_id IS NOT NULL AND jenis_pelaksanaan='online' THEN 'Selesai' ELSE 'Siap Dikerjakan' END,completed_at=CASE WHEN lamaran_id IS NOT NULL AND jenis_pelaksanaan='online' THEN COALESCE(completed_at,NOW()) ELSE completed_at END WHERE id=?")->execute([$p['pesanan_id']]);$q=$pdo->prepare('SELECT pembeli_id,pekerja_id,kode_pesanan,lamaran_id,jenis_pelaksanaan FROM pesanan WHERE id=?');$q->execute([$p['pesanan_id']]);$o=$q->fetch();notify($pdo,(int)$o['pembeli_id'],'pembayaran','Pembayaran berhasil','Pembayaran pesanan '.$o['kode_pesanan'].' berhasil.','/penyedia/tahap4-pesanan.php?id='.$p['pesanan_id']);if(!empty($o['lamaran_id']) && $o['jenis_pelaksanaan']==='online'){t4_credit_worker_after_completion($pdo,(int)$p['pesanan_id'],(int)$u['id']);}else{notify($pdo,(int)$o['pekerja_id'],'pembayaran','Pembayaran terverifikasi','Pembayaran pesanan '.$o['kode_pesanan'].' telah diverifikasi.','/pekerja/tahap4-pesanan.php?id='.$p['pesanan_id']);}}elseif($decision==='reject'){$pdo->prepare("UPDATE pembayaran SET status='Gagal',diverifikasi_at=NOW(),diverifikasi_oleh=?,catatan_verifikasi=? WHERE id=?")->execute([$u['id'],$note?:'Bukti tidak valid',$pid]);$pdo->prepare("UPDATE invoice SET status='Belum Dibayar' WHERE id=?")->execute([$p['invoice_id']]);$pdo->prepare("UPDATE pesanan SET status_pembayaran='Gagal' WHERE id=?")->execute([$p['pesanan_id']]);}else throw new RuntimeException('Keputusan tidak valid.');t4_audit($pdo,(int)$u['id'],'payment.'.$decision,'pembayaran',$pid);$pdo->commit();}else throw new RuntimeException('Aksi tidak valid.');t4_flash_redirect('Perubahan tersimpan.','/admin/tahap4-transaksi.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$err=$e instanceof RuntimeException?$e->getMessage():'Tidak dapat memproses aksi.';error_log('admin t4: '.$e->getMessage());}}
$q=$pdo->query('SELECT * FROM aturan_komisi ORDER BY created_at DESC LIMIT 10');$rules=$q->fetchAll();$q=$pdo->query("SELECT p.*,i.kode_invoice,i.total_tagihan,o.kode_pesanan,o.nama_jasa,b.nama nama_pembeli FROM pembayaran p JOIN invoice i ON i.id=p.invoice_id JOIN pesanan o ON o.id=i.pesanan_id JOIN users b ON b.id=o.pembeli_id WHERE p.status='Menunggu Verifikasi' ORDER BY p.created_at");$pending=$q->fetchAll();$q=$pdo->query("SELECT p.*,i.kode_invoice,o.kode_pesanan,o.nama_jasa FROM pembayaran p JOIN invoice i ON i.id=p.invoice_id JOIN pesanan o ON o.id=i.pesanan_id WHERE p.raw_status='duplicate_payment_review' ORDER BY p.updated_at DESC LIMIT 30");$duplicatePayments=$q->fetchAll();$pageTitle='Admin transaksi';require __DIR__.'/../includes/header.php';?><main class="dashboard-main"><p class="eyebrow">Administrasi</p><h1 class="dashboard-title">Pengaturan & verifikasi transaksi</h1><p class="text-sm text-slate-500 mb-5">Komisi tetap 10% (5% pembeli + 5% pekerja). <a class="text-teal-700 underline" href="<?=BASE_URL?>/admin/pencairan.php">Kelola pencairan pekerja →</a></p><?php if($err):?><div class="alert alert-error mb-4"><?=e($err)?></div><?php endif?><section class="dashboard-panel mb-6"><h2 class="font-bold text-xl mb-3">Aturan komisi platform</h2><form method="post" class="grid md:grid-cols-3 gap-3"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="commission"><label>Nama aturan<input class="form-control" name="nama" value="Komisi NusaKarya" required></label><label>Total komisi platform<input class="form-control" value="10% (5% pembeli + 5% pekerja)" readonly></label><div class="flex items-end"><button class="btn-primary">Aktifkan aturan baru</button></div></form><p class="text-xs text-slate-500 mt-2">Komisi dikunci 10%: 5% dibayar pembeli dan 5% dipotong dari pendapatan pekerja. Biaya gateway ditanggung NusaKarya.</p><?php foreach($rules as $r):?><p class="text-sm mt-2"><?=e($r['nama'])?> — <?=number_format((float)$r['persentase'],2)?>% — <?=$r['is_aktif']?'Aktif':'Arsip'?></p><?php endforeach?></section><section class="dashboard-panel"><h2 class="font-bold text-xl mb-3">Bukti pembayaran menunggu verifikasi</h2><?php foreach($pending as $p):?><article class="border rounded-xl p-4 mb-3"><div class="flex flex-wrap justify-between gap-2"><b><?=e($p['kode_pesanan'])?> · <?=e($p['nama_jasa'])?></b><b><?=rupiah($p['total_tagihan'])?></b></div><p class="text-sm text-slate-500">Pembeli: <?=e($p['nama_pembeli'])?> · <?=e($p['kode_invoice'])?></p><?php if($p['bukti_path']):?><a class="text-teal-700 underline text-sm" target="_blank" rel="noopener" href="<?=BASE_URL?>/admin/bukti-pembayaran.php?id=<?=(int)$p['id']?>">Lihat bukti pembayaran</a><?php endif?><form method="post" class="mt-3 flex flex-wrap gap-2"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="verify"><input type="hidden" name="payment_id" value="<?=(int)$p['id']?>"><input class="form-control flex-1 min-w-48" name="note" placeholder="Catatan verifikasi"><button class="btn-primary" name="decision" value="approve">Verifikasi berhasil</button><button class="btn-secondary" name="decision" value="reject">Tolak bukti</button></form></article><?php endforeach?><?php if(!$pending):?><p class="empty-state">Tidak ada pembayaran yang menunggu verifikasi.</p><?php endif?></section><section class="dashboard-panel mt-6"><h2 class="font-bold text-xl mb-3">Pembayaran ganda yang perlu diperiksa</h2><?php foreach($duplicatePayments as $dp):?><article class="border rounded-xl p-3 mb-2"><b><?=e($dp['kode_pesanan'])?> · <?=e($dp['nama_jasa'])?></b><p class="text-sm text-rose-700">Pembayaran tambahan <?=rupiah($dp['jumlah'])?> terdeteksi setelah invoice lunas. Periksa dan tindak lanjuti refund secara manual.</p><p class="text-xs text-slate-500"><?=e($dp['kode_pembayaran'])?> · <?=e($dp['provider_reference']??'')?></p></article><?php endforeach?><?php if(!$duplicatePayments):?><p class="empty-state">Tidak ada pembayaran ganda yang perlu diperiksa.</p><?php endif?></section></main><?php require __DIR__.'/../includes/footer.php';?>
